        "2x + 52 = 2(x − 4) + 60（2x − 8 + 60 = 2x + 52 ✓）→ y = 2 + 60/(x − 4)：x − 4 が 60 の約数（±1, 2, 3, 4, 5, 6, 10, 12, 15, 20, 30, 60）→ 12 × 2 = 24 個",
